from __future__ import annotations
import math

def gamma_term(k: int) -> float:
    if k < 0:
        raise ValueError("k must be nonnegative")
    x = 1.0 / (k + 1.0)
    return x - math.log1p(x)

def accumulated_information(n: int) -> float:
    if n < 0:
        raise ValueError("n must be nonnegative")
    return math.fsum(gamma_term(k) for k in range(n))

def harmonic_log_form(n: int) -> float:
    harmonic = math.fsum(1.0 / j for j in range(1, n + 1))
    return harmonic - math.log(n + 1.0)

if __name__ == "__main__":
    for n in (1, 10, 100, 10_000):
        a = accumulated_information(n)
        b = harmonic_log_form(n)
        print(n, f"{a:.15f}", f"{b:.15f}", f"difference={abs(a-b):.3e}")

from __future__ import annotations
import math

def gamma_term(k: int) -> float:
    x = 1.0 / (k + 1.0)
    return x - math.log1p(x)

def inspect_bounds(count: int) -> None:
    if count < 0:
        raise ValueError("count must be nonnegative")
    print("k, term, rational majorant, inverse-square majorant, term/square")
    for k in range(count):
        term = gamma_term(k)
        rational = 1.0 / ((k + 1.0) * (2.0 * k + 3.0))
        square = 1.0 / (2.0 * (k + 1.0) ** 2)
        assert 0.0 < term <= rational <= square
        print(k, term, rational, square, term / square)

if __name__ == "__main__":
    inspect_bounds(20)

from __future__ import annotations
import math

def exponential_kl(a: float, b: float) -> float:
    if a <= 0.0 or b <= 0.0:
        raise ValueError("rates must be positive")
    relative_change = (b - a) / a
    return relative_change - math.log1p(relative_change)

def diagnose(a: float, b: float, scale: float) -> None:
    if scale <= 0.0:
        raise ValueError("scale must be positive")
    forward = exponential_kl(a, b)
    reverse = exponential_kl(b, a)
    square = (a - b) ** 2 / (a * b)
    print(f"D(a||b)={forward:.15g}")
    print(f"D(b||a)={reverse:.15g}")
    print(f"D(ca||cb)={exponential_kl(scale*a, scale*b):.15g}")
    print(f"symmetrized={forward+reverse:.15g}; square={square:.15g}")

if __name__ == "__main__":
    diagnose(3.0, 7.0, 11.0)

